pub struct ExactFactory;
impl semio_framework::ToolJobFactory for ExactFactory {
 type Job = ExactJob;
 fn create_job(&mut self, operation: Operation, payload: Payload) -> Result<ExactJob, Error> { ExactJob::new(operation, payload) }
 fn execution_contract(&self) -> Contract { bounded_contract() }
}
impl semio_framework_plugin::ArtifactOwnedToolJobFactory for ExactFactory {
 type Owner = semio_framework_plugin::EditorApp<ExactOwner>;
 const TOOL_IDS: &'static [&'static str] = &["bounded"];
 const DOCUMENT_SCHEMA: &'static str = "fixture.document";
 const PUBLICATION_CONTRACTS: &'static [ArtifactToolPublicationContract] = &[ArtifactToolPublicationContract { tool_id: "bounded", lanes: &[ArtifactToolPublicationLane::HostOnly] }];
}
pub struct OtherFactory;
impl semio_framework::ToolJobFactory for OtherFactory { type Job = OtherJob; fn create_job(&mut self, operation: Operation, payload: Payload) -> Result<OtherJob, Error> { OtherJob::new(operation, payload) } fn execution_contract(&self) -> Contract { bounded_contract() } }
impl semio_framework_plugin::ArtifactOwnedToolJobFactory for OtherFactory { type Owner = semio_framework_plugin::EditorApp<ExactOwner>; const TOOL_IDS: &'static [&'static str] = &["other"]; }
pub const EXACT_DOCUMENT_SCHEMA: &str = ExactSnapshot::SCHEMA;
impl ExactSnapshot { pub const SCHEMA: &'static str = "fixture.document"; }
impl WrongSnapshot { pub const SCHEMA: &'static str = "wrong.document"; }

